<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/AdminOperationsService.php';$svc=new AdminOperationsService(Database::connection());$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$rows=$svc->transactionSearch($q,$status);$statuses=['processing','completed','failed','reversed','refunded'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Transactions - Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2>Transaction Operations</h2><a href="<?=url('admin/')?>">Admin dashboard</a></div><form class="row g-2 mb-4"><div class="col-md-5"><input name="q" value="<?=e($q)?>" class="form-control" placeholder="Reference, email, account or description"></div><div class="col-md-3"><select name="status" class="form-select"><option value="">All statuses</option><?php foreach($statuses as $s):?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-primary">Search</button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Reference</th><th>Type</th><th>Amount</th><th>Status</th><th>Customer</th><th>Account</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['reference'])?></td><td><?=e($r['type'])?></td><td>$<?=number_format((float)$r['amount'],2)?></td><td><span class="badge text-bg-secondary"><?=e($r['status'])?></span></td><td><?=e($r['email']??'—')?></td><td><?=e($r['account_number']??'—')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></body></html>
